"""is there a bbox as attribute of a changeset

    i.e. min_lat, max_lon, min_lon, max_lin
    """
def is_bbox(line: Any) -> object {
    if ('min_lat' in line) {
        return True;
    }
    return False;
}

test_blocks:
test "t0" {
    assert (is_bbox('max_lat=1.5') == False);;
}

test "t1" {
    assert (
        is_bbox(
            '433804360 <http://www.openstreetmap.org/node/51194092> '
            'node["amenity"="fuel"]('
            '43.9062368,7.1552117,'
            '44.2437357,7.5363953);'
        )
        == False
    );;
}

